'use strict';

/**
 * Generated by `aid infra gen`. Do not edit: the next run refuses to overwrite a
 * hand-edited file, and the construct carries no project-specific fact to keep.
 *
 * The AWS CDK spelling of `infra/generated/modules/container`: an ECS Fargate service per
 * `container` deployment behind one application load balancer, with a target group per
 * service and one listener rule per declared path. It reads the same context document the
 * module reads, so the two backends cannot drift.
 *
 * Business inputs stay inputs: the image each service runs, the ARN of each secret,
 * per-service sizing, and the network arrive in `inputs`, never in the generated tree.
 *
 * Streaming is allowed here, unlike `serverless.cjs`: an ALB delivers a response body
 * incrementally, which is what an HTTP API cannot do.
 */

const cdk = require('aws-cdk-lib');
const bedrock = require('aws-cdk-lib/aws-bedrock');
const ec2 = require('aws-cdk-lib/aws-ec2');
const ecs = require('aws-cdk-lib/aws-ecs');
const elbv2 = require('aws-cdk-lib/aws-elasticloadbalancingv2');
const iam = require('aws-cdk-lib/aws-iam');
const logs = require('aws-cdk-lib/aws-logs');

// The generated Dockerfile listens on this port and reads no other.
const PORT = 8080;

/**
 * IAM, ECS and ALB names allow letters, digits and hyphens only, while a namespace may
 * carry a dot; the scan is what keeps `aid.test` a legal name. Scanning once instead of
 * replacing with a regular expression keeps caller input away from one.
 */
function sanitize(value) {
  const source = String(value);
  let out = '';
  for (let index = 0; index < source.length; index += 1) {
    const code = source.charCodeAt(index);
    const digit = code >= 48 && code <= 57;
    const upper = code >= 65 && code <= 90;
    const lower = code >= 97 && code <= 122;
    if (digit || upper || lower || code === 45) {
      out += source.charAt(index);
    } else if (!out.endsWith('-')) {
      out += '-';
    }
  }
  while (out.endsWith('-')) out = out.slice(0, -1);
  return out;
}

// A truncation can land on a separator, and two names would then collide on it.
function limited(value, length) {
  let out = value.slice(0, length);
  while (out.endsWith('-')) out = out.slice(0, -1);
  return out;
}

// The shortest of the limits the resources below impose is an ALB name, at 32.
function prefixOf(project) {
  return limited(sanitize(project.namespace + '-' + project.name), 24);
}

function nameOf(project, id) {
  return limited(sanitize(prefixOf(project) + '-' + id), 32);
}

function applyTags(resource, inputs) {
  for (const key of Object.keys(inputs.tags || {})) {
    cdk.Tags.of(resource).add(key, inputs.tags[key]);
  }
}

/**
 * Provision the managed guardrail for one service, and nothing when the spec leaves it to
 * its operator. The HCL module spells the same two resources, so the two backends must
 * agree about which service owns a guardrail and which immutable version the app calls.
 */
function addGuardrail(scope, context, id, service, role) {
  if (!(service.guardrailEngines || []).includes('bedrock')) return undefined;

  const policy = (context.guardrails || {})[id];
  if (!policy) return undefined;

  // A guardrail name caps at 50 characters and allows letters, digits, hyphens and
  // underscores; `nameOf` is already sanitised, so only the cap is left.
  const props = {
    name: (nameOf(context.project, id) + '-guardrail').slice(0, 50),
    description: policy.message,
    blockedInputMessaging: policy.message,
    blockedOutputsMessaging: policy.message,
  };

  if (policy.content.length > 0) {
    props.contentPolicyConfig = {
      filtersConfig: policy.content.map((filter) => ({
        type: filter.type,
        inputStrength: filter.strength,
        outputStrength: filter.strength,
      })),
    };
  }

  if (policy.topics.length > 0) {
    props.topicPolicyConfig = {
      topicsConfig: policy.topics.map((topic) => ({
        name: topic.name,
        definition: topic.definition,
        type: 'DENY',
      })),
    };
  }

  // Only the author's own words, never a managed list: adding one here would block
  // vocabulary the spec did not ask for.
  if (policy.words.length > 0) {
    props.wordPolicyConfig = {
      wordsConfig: policy.words.map((text) => ({ text: text })),
    };
  }

  if (policy.pii.length > 0) {
    props.sensitiveInformationPolicyConfig = {
      piiEntitiesConfig: policy.pii.map((entity) => ({
        type: entity.type,
        action: entity.action,
      })),
    };
  }

  const guardrail = new bedrock.CfnGuardrail(scope, id + 'Guardrail', props);

  // A guardrail is mutable and every change mints a new immutable version, so the app is
  // pinned to this one. Pointing it at DRAFT would let a later edit change a live
  // deployment without a plan.
  const version = new bedrock.CfnGuardrailVersion(scope, id + 'GuardrailVersion', {
    guardrailIdentifier: guardrail.attrGuardrailId,
    description: 'Published by aid infra gen from the spec.',
  });

  // Evaluating a guardrail is the app's job; provisioning it is this construct's. Scoping
  // the grant to the ARN means a compromised task cannot apply another guardrail.
  role.addToPolicy(
    new iam.PolicyStatement({
      actions: ['bedrock:ApplyGuardrail'],
      resources: [guardrail.attrGuardrailArn],
    }),
  );

  return { guardrail: guardrail, version: version };
}

/**
 * Add every `container` service in `context` to `scope`.
 *
 * A refusal throws with the same sentence the OpenTofu module puts in a precondition, so
 * `cdk synth` fails for the reason `tofu plan` would: a service needs an image, a declared
 * secret needs its ARN, one path belongs to one service, and the network needs two AZs.
 */
function addContainer(scope, context, inputs) {
  const services = context.services || {};
  const ids = Object.keys(services).filter((id) => services[id].target === 'container');
  if (ids.length === 0) return {};

  const images = inputs.images || {};
  const secretArns = inputs.secretArns || {};
  const sizing = inputs.sizing || {};
  const project = context.project;
  const region = inputs.bedrockRegion || cdk.Aws.REGION;

  for (const id of ids) {
    const service = services[id];
    if (!images[id]) {
      throw new Error(
        'No images entry for "' + id + '". Name the released tag this service runs; ' +
          'the spec names a repository, not a tag.',
      );
    }
    for (const variable of service.env) {
      if (variable.secret && !secretArns[variable.name]) {
        throw new Error(
          'Service "' + id + '" references a secret with no secretArns entry. ' +
            'Add name -> ARN for every secret it declares.',
        );
      }
    }
  }

  // One entry per (service, path). The ALB matches a path and not a method, so a path
  // belongs to one service; a second claimant is refused rather than collapsed.
  const paths = {};
  for (const id of ids) {
    const claimed = {};
    for (const route of services[id].routes || []) {
      if (claimed[route.path]) continue;
      claimed[route.path] = true;
      if (paths[route.path] !== undefined && paths[route.path] !== id) {
        throw new Error(
          'Two container services declare the same path. An ALB routes by path, not by ' +
            'method, so one path must belong to one service.',
        );
      }
      paths[route.path] = id;
    }
  }
  const routePaths = Object.keys(paths).sort();

  // Networking can be created or brought: set vpcId and both subnet lists to use a VPC
  // that already exists, or leave them empty and the construct builds a two-AZ VPC with
  // private task subnets and one NAT gateway.
  let vpcId;
  let publicSubnetIds;
  let privateSubnetIds;

  if (inputs.vpcId) {
    vpcId = inputs.vpcId;
    publicSubnetIds = inputs.publicSubnetIds || [];
    privateSubnetIds = inputs.privateSubnetIds || [];
  } else {
    if (!inputs.vpcCidr) {
      throw new Error(
        'The construct builds a VPC because vpcId is empty, so vpcCidr must name the ' +
          'range it should use. Set vpcId plus both subnet lists to deploy into a VPC ' +
          'you already run.',
      );
    }

    // Laid out with L1 resources rather than ec2.Vpc: the L2 asks the account for its
    // availability zones, and cdk synth runs without credentials. Spreading the block by
    // an 8-bit step into /24s mirrors the Terraform module's cidrsubnet calls, so both
    // backends describe the same network.
    const prefixLength = Number(String(inputs.vpcCidr).split('/')[1]);
    const sizeMask = Number.isFinite(prefixLength) ? Math.max(0, 24 - prefixLength) : 8;
    const subnetCidr = (index) =>
      cdk.Fn.select(index, cdk.Fn.cidr(inputs.vpcCidr, 16, sizeMask));
    const zones = inputs.availabilityZones || [
      cdk.Aws.REGION + 'a',
      cdk.Aws.REGION + 'b',
    ];

    const vpc = new ec2.CfnVPC(scope, 'Vpc', {
      cidrBlock: inputs.vpcCidr,
      enableDnsSupport: true,
      enableDnsHostnames: true,
    });
    applyTags(vpc, inputs);

    const internetGateway = new ec2.CfnInternetGateway(scope, 'InternetGateway', {});
    applyTags(internetGateway, inputs);

    const attachment = new ec2.CfnVPCGatewayAttachment(scope, 'GatewayAttachment', {
      vpcId: vpc.ref,
      internetGatewayId: internetGateway.ref,
    });

    const publicSubnets = [0, 1].map((index) => {
      const subnet = new ec2.CfnSubnet(scope, 'PublicSubnet' + index, {
        vpcId: vpc.ref,
        cidrBlock: subnetCidr(index),
        availabilityZone: zones[index],
        mapPublicIpOnLaunch: true,
      });
      applyTags(subnet, inputs);
      cdk.Tags.of(subnet).add('Name', prefixOf(project) + '-public-' + index);
      return subnet;
    });

    const privateSubnets = [0, 1].map((index) => {
      const subnet = new ec2.CfnSubnet(scope, 'PrivateSubnet' + index, {
        vpcId: vpc.ref,
        cidrBlock: subnetCidr(index + 10),
        availabilityZone: zones[index],
      });
      applyTags(subnet, inputs);
      cdk.Tags.of(subnet).add('Name', prefixOf(project) + '-private-' + index);
      return subnet;
    });

    const publicRoutes = new ec2.CfnRouteTable(scope, 'PublicRouteTable', { vpcId: vpc.ref });
    applyTags(publicRoutes, inputs);
    new ec2.CfnRoute(scope, 'InternetRoute', {
      routeTableId: publicRoutes.ref,
      destinationCidrBlock: '0.0.0.0/0',
      gatewayId: internetGateway.ref,
    });
    publicSubnets.forEach((subnet, index) =>
      new ec2.CfnSubnetRouteTableAssociation(scope, 'PublicRouteAssociation' + index, {
        subnetId: subnet.ref,
        routeTableId: publicRoutes.ref,
      }),
    );

    const natAddress = new ec2.CfnEIP(scope, 'NatAddress', { domain: 'vpc' });
    applyTags(natAddress, inputs);
    const natGateway = new ec2.CfnNatGateway(scope, 'NatGateway', {
      allocationId: natAddress.attrAllocationId,
      subnetId: publicSubnets[0].ref,
    });
    // A NAT gateway needs the gateway attachment to reach AWS, which Terraform orders
    // explicitly; CloudFormation reads the dependency from the graph instead.
    natGateway.addDependency(attachment);
    applyTags(natGateway, inputs);

    const privateRoutes = new ec2.CfnRouteTable(scope, 'PrivateRouteTable', { vpcId: vpc.ref });
    applyTags(privateRoutes, inputs);
    new ec2.CfnRoute(scope, 'EgressRoute', {
      routeTableId: privateRoutes.ref,
      destinationCidrBlock: '0.0.0.0/0',
      natGatewayId: natGateway.ref,
    });
    privateSubnets.forEach((subnet, index) =>
      new ec2.CfnSubnetRouteTableAssociation(scope, 'PrivateRouteAssociation' + index, {
        subnetId: subnet.ref,
        routeTableId: privateRoutes.ref,
      }),
    );

    vpcId = vpc.ref;
    publicSubnetIds = publicSubnets.map((subnet) => subnet.ref);
    privateSubnetIds = privateSubnets.map((subnet) => subnet.ref);
  }

  // An empty subnet list is a valid object and an invalid service, so the failure is
  // named here rather than surfacing as "subnets must not be empty" mid-deploy.
  if (privateSubnetIds.length < 2) {
    throw new Error(
      'Tasks need two private subnets in different availability zones. Supply ' +
        'privateSubnetIds alongside vpcId, or leave vpcId empty to have the construct ' +
        'build a VPC.',
    );
  }

  if (routePaths.length > 0 && publicSubnetIds.length < 2) {
    throw new Error(
      'A load balancer needs at least two subnets in different availability zones. ' +
        'Supply publicSubnetIds, or leave vpcId empty to have the construct build a VPC.',
    );
  }

  const albGroup =
    routePaths.length > 0
      ? new ec2.CfnSecurityGroup(scope, 'AlbSecurityGroup', {
          groupName: limited(prefixOf(project) + '-alb', 32),
          groupDescription: 'Ingress to the generated load balancer.',
          vpcId: vpcId,
          securityGroupIngress: [
            {
              description:
                'HTTP from anywhere. Terminate TLS in front of this when you need it.',
              ipProtocol: 'tcp',
              fromPort: 80,
              toPort: 80,
              cidrIp: '0.0.0.0/0',
            },
          ],
          securityGroupEgress: [{ ipProtocol: '-1', cidrIp: '0.0.0.0/0' }],
        })
      : undefined;
  if (albGroup) applyTags(albGroup, inputs);

  const taskGroup = new ec2.CfnSecurityGroup(scope, 'TaskSecurityGroup', {
    groupName: limited(prefixOf(project) + '-task', 32),
    groupDescription: 'Only the load balancer may reach a task; tasks may reach anything.',
    vpcId: vpcId,
    securityGroupEgress: [{ ipProtocol: '-1', cidrIp: '0.0.0.0/0' }],
  });
  applyTags(taskGroup, inputs);

  if (albGroup) {
    new ec2.CfnSecurityGroupIngress(scope, 'TaskFromAlb', {
      groupId: taskGroup.attrGroupId,
      sourceSecurityGroupId: albGroup.attrGroupId,
      description: 'The generated load balancer is the only caller.',
      ipProtocol: 'tcp',
      fromPort: PORT,
      toPort: PORT,
    });
  }

  const clusterName = limited(prefixOf(project) + '-cluster', 255);
  const cluster = new ecs.CfnCluster(scope, 'Cluster', { clusterName: clusterName });
  applyTags(cluster, inputs);

  const servicesById = {};
  const targetGroups = {};

  for (const id of ids) {
    const service = services[id];
    const name = nameOf(project, id);
    const hasRoute = routePaths.some((path) => paths[path] === id);

    // The execution role, not the task role, reads a secret before the container starts.
    const executionRole = new iam.Role(scope, id + 'ExecutionRole', {
      roleName: limited(name + '-exec', 64),
      assumedBy: new iam.ServicePrincipal('ecs-tasks.amazonaws.com'),
      managedPolicies: [
        iam.ManagedPolicy.fromAwsManagedPolicyName(
          'service-role/AmazonECSTaskExecutionRolePolicy',
        ),
      ],
    });
    if (Object.keys(secretArns).length > 0) {
      executionRole.addToPolicy(
        new iam.PolicyStatement({
          actions: ['secretsmanager:GetSecretValue'],
          resources: Object.keys(secretArns).map((secret) => secretArns[secret]),
        }),
      );
    }

    const taskRole = new iam.Role(scope, id + 'TaskRole', {
      roleName: limited(name + '-task', 64),
      assumedBy: new iam.ServicePrincipal('ecs-tasks.amazonaws.com'),
    });

    // Bedrock authenticates with this role, so the task needs no API key. The stream action
    // is granted only to a service that streams.
    const usesBedrock = (service.providers || []).includes('bedrock');
    if (usesBedrock) {
      taskRole.addToPolicy(
        new iam.PolicyStatement({
          actions: ['bedrock:InvokeModel'].concat(
            service.streaming ? ['bedrock:InvokeModelWithResponseStream'] : [],
          ),
          resources: [
            'arn:' + cdk.Aws.PARTITION + ':bedrock:*::foundation-model/*',
            'arn:' +
              cdk.Aws.PARTITION +
              ':bedrock:*:' +
              cdk.Aws.ACCOUNT_ID +
              ':inference-profile/*',
          ],
        }),
      );
    }

    // Retrieve is the only call a managed base is used for: generation stays in this
    // project, where the model gate, the guardrail and the cost ledger can see it. The id
    // and ARN arrive in `inputs` because the context is written before anything is
    // applied, and a policy with an empty resource is invalid rather than merely empty.
    const providedBases = inputs.knowledgeBases || {};
    const declaredBases = context.knowledgeBases || {};
    const bases = Object.keys(declaredBases)
      .filter(
        (baseId) => declaredBases[baseId].engine === 'aws-bedrock' && providedBases[baseId],
      )
      .map((baseId) =>
        Object.assign({}, declaredBases[baseId], {
          id: providedBases[baseId].id,
          arn: providedBases[baseId].arn,
        }),
      );
    const existingBases = bases.filter((base) => base.id && base.arn);
    if (existingBases.length > 0) {
      taskRole.addToPolicy(
        new iam.PolicyStatement({
          actions: ['bedrock:Retrieve'],
          resources: existingBases.map((base) => base.arn),
        }),
      );
    }

    // Later assignments win, matching the module's merge order: the region first, then the
    // spec's literals, then the resources the construct owns.
    const variables = {};
    if (usesBedrock) variables.AWS_REGION = region;
    for (const variable of service.env) {
      if (!variable.secret && variable.value !== undefined) {
        variables[variable.name] = variable.value;
      }
    }

    const managed = addGuardrail(scope, context, id, service, taskRole);
    if (managed) {
      variables.BEDROCK_GUARDRAIL_ID = managed.guardrail.attrGuardrailId;
      variables.BEDROCK_GUARDRAIL_VERSION = managed.version.attrVersion;
    }

    // Only a service that binds one of the base's retrievers learns the id, and only once
    // the base exists: the runtime raises a named error for a missing id, while an empty
    // string would read as a created base with an empty corpus.
    for (const base of existingBases) {
      const bound = (base.retrievers || []).some((retriever) =>
        (service.ingest || []).includes(retriever),
      );
      if (bound) variables[base.envName] = base.id;
    }

    const logGroupName = '/aws/ecs/' + name;
    const logGroup = new logs.CfnLogGroup(scope, id + 'LogGroup', {
      logGroupName: logGroupName,
      retentionInDays: inputs.logRetentionDays || 30,
    });
    applyTags(logGroup, inputs);

    const taskDefinition = new ecs.CfnTaskDefinition(scope, id + 'TaskDefinition', {
      family: name,
      cpu: String((sizing[id] && sizing[id].cpu) || 512),
      memory: String((sizing[id] && sizing[id].memoryMb) || 1024),
      networkMode: 'awsvpc',
      requiresCompatibilities: ['FARGATE'],
      executionRoleArn: executionRole.roleArn,
      taskRoleArn: taskRole.roleArn,
      containerDefinitions: [
        {
          name: 'app',
          image: images[id],
          essential: true,
          portMappings: [{ containerPort: PORT, protocol: 'tcp' }],
          environment: Object.keys(variables).map((key) => ({
            name: key,
            value: variables[key],
          })),
          secrets: service.env
            .filter((variable) => variable.secret)
            .map((variable) => ({
              name: variable.name,
              valueFrom: secretArns[variable.name],
            })),
          logConfiguration: {
            logDriver: 'awslogs',
            options: {
              'awslogs-group': logGroupName,
              'awslogs-region': cdk.Aws.REGION,
              'awslogs-stream-prefix': 'ecs',
            },
          },
        },
      ],
    });
    applyTags(taskDefinition, inputs);

    if (hasRoute) {
      // Any answer up to 499 proves the process is serving; requiring 200 would fail a
      // service whose every route sits behind authentication.
      targetGroups[id] = new elbv2.CfnTargetGroup(scope, id + 'TargetGroup', {
        name: limited(name + '-tg', 32),
        port: PORT,
        protocol: 'HTTP',
        targetType: 'ip',
        vpcId: vpcId,
        healthCheckPath: inputs.healthCheckPath || '/',
        healthCheckProtocol: 'HTTP',
        healthCheckMatcher: { httpCode: '200-499' },
      });
      applyTags(targetGroups[id], inputs);
    }

    const serviceProps = {
      serviceName: name,
      cluster: clusterName,
      taskDefinition: taskDefinition.ref,
      desiredCount: (sizing[id] && sizing[id].desiredCount) || 1,
      launchType: 'FARGATE',
      networkConfiguration: {
        awsvpcConfiguration: {
          subnets: privateSubnetIds,
          securityGroups: [taskGroup.attrGroupId],
          assignPublicIp: 'DISABLED',
        },
      },
      // A task the platform cannot place must fail the deploy, not sit pending forever.
      deploymentConfiguration: { deploymentCircuitBreaker: { enable: true, rollback: true } },
    };

    if (hasRoute) {
      // Registering with the target group is what puts a task behind the listener; a
      // service that routes nowhere deliberately has no load balancer to join.
      serviceProps.loadBalancers = [
        {
          containerName: 'app',
          containerPort: PORT,
          targetGroupArn: targetGroups[id].ref,
        },
      ];
      // The probe starts before the app has finished importing, so give it room rather
      // than let the scheduler replace a task that was merely still starting.
      serviceProps.healthCheckGracePeriodSeconds = 60;
    }

    servicesById[id] = new ecs.CfnService(scope, id + 'Service', serviceProps);
    applyTags(servicesById[id], inputs);
  }

  let loadBalancer;
  if (routePaths.length > 0) {
    loadBalancer = new elbv2.CfnLoadBalancer(scope, 'LoadBalancer', {
      name: limited(prefixOf(project) + '-alb', 32),
      type: 'application',
      scheme: 'internet-facing',
      subnets: publicSubnetIds,
      securityGroups: [albGroup.attrGroupId],
      idleTimeout: String(inputs.idleTimeout || 300),
      ipAddressType: 'ipv4',
    });
    applyTags(loadBalancer, inputs);

    const listener = new elbv2.CfnListener(scope, 'HttpListener', {
      loadBalancerArn: loadBalancer.ref,
      port: 80,
      protocol: 'HTTP',
      defaultActions: [
        {
          type: 'fixed-response',
          fixedResponseConfig: {
            statusCode: '404',
            contentType: 'text/plain',
            messageBody: 'no route',
          },
        },
      ],
    });
    applyTags(listener, inputs);

    // Priorities come from the sorted path order, so the same plan always assigns the same
    // numbers; adding a path may renumber the ones after it, which is a diff, not a drift.
    routePaths.forEach((path, index) => {
      new elbv2.CfnListenerRule(scope, 'PathRule' + (index + 1), {
        listenerArn: listener.ref,
        priority: index + 1,
        actions: [
          { type: 'forward', targetGroupArn: targetGroups[paths[path]].ref },
        ],
        conditions: [{ field: 'path-pattern', pathPatternConfig: { values: [path] } }],
      });
    });
  }

  const endpoint = loadBalancer ? 'http://' + loadBalancer.attrDnsName : '';

  // Named apart from the serverless construct's outputs: both are added to one stack, and
  // a construct id is unique per scope.
  new cdk.CfnOutput(scope, 'ContainerEndpoint', {
    description: 'The load balancer base URL, empty when the plan declares no routes.',
    value: endpoint,
  });
  new cdk.CfnOutput(scope, 'ContainerClusterName', {
    description: 'The ECS cluster every container service joins.',
    value: clusterName,
  });

  return { endpoint: endpoint, services: servicesById, cluster: clusterName };
}

module.exports = { addContainer: addContainer };
